from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    main = {v for v, n in counts.items() if v != bg and n >= 8}
    out = [[bg] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in main or seen[r][c]:
                continue
            comp = [(r, c)]
            seen[r][c] = True
            for y, x in comp:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        comp.append((ny, nx))
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            area = (r1-r0+1) * (c1-c0+1)
            if area < 4 or len(comp) / area < 0.60:
                continue
            # Fill component bounding box, and recover an occluded edge only
            # when the enlarged rectangle is still almost entirely non-background.
            changed = True
            while changed:
                changed = False
                for nr0, nr1, nc0, nc1 in ((r0,r1,c0-1,c1),(r0,r1,c0,c1+1),(r0-1,r1,c0,c1),(r0,r1+1,c0,c1)):
                    if nr0 < 0 or nr1 >= h or nc0 < 0 or nc1 >= w:
                        continue
                    a = (nr1-nr0+1)*(nc1-nc0+1)
                    coln = sum(grid[y][x] == color for y in range(nr0,nr1+1) for x in range(nc0,nc1+1))
                    nonbg = sum(grid[y][x] != bg for y in range(nr0,nr1+1) for x in range(nc0,nc1+1))
                    if coln >= 4 and coln/a >= 0.70 and nonbg/a >= 0.90:
                        r0,r1,c0,c1 = nr0,nr1,nc0,nc1
                        changed = True
                        break
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    out[y][x] = color
    return out

